function stats(id){const r=S.reviews.filter(x=>x.ownerId===id&&x.type!=='rating'),p=r.filter(x=>x.paid).length,ratings=S.reviews.filter(x=>x.type==='rating'&&x.targetId===id);return{n:r.length,p,pct:r.length?Math.round(p/r.length*100):null,list:r.slice(-5).reverse(),ratingCount:ratings.length,ratingAvg:ratings.length?ratings.reduce((a,x)=>a+x.stars,0)/ratings.length:0,ratingList:ratings.slice(-5).reverse()}}
const trust=(u,s)=>u.verified&&s.n>=3&&s.pct>=80?'Pagador de confiança':s.n?(s.pct>=80?'Bom histórico de pagamentos':'Histórico de pagamentos irregular'):'Ainda sem histórico de pagamentos';
function profile(u){const s=stats(u.id),own=S.me&&S.me.id===u.id,earnings=own?S.me?.earnings:u.earnings,canRate=S.me&&!own&&S.cands.some(c=>c.status==='pago'&&((c.userId===S.me.id&&c.ownerId===u.id)||(c.ownerId===S.me.id&&c.userId===u.id))),already=S.reviews.some(x=>x.type==='rating'&&x.targetId===u.id&&x.reviewerId===S.me?.id);const stars=starsHtml;return`<div class="pf">${av(u,72)}<h2>${esc(u.nome)} ${u.verified?ic('badge','ok'):''}</h2><p class="mut">${trust(u,s)}</p>${u.cidade?`<p class="mut">${ic('pin','s')} ${esc(u.cidade)}</p>`:''}</div><div class="gr"><div><b>${u.verified?'Sim':'Não'}</b><small>Verificado</small></div><div><b>${s.n}</b><small>Interações concluídas</small></div><div><b>${s.ratingCount?`<span class="inl">${s.ratingAvg.toFixed(1)} ${ic('star','fill star s')}</span>`:'—'}</b><small>${s.ratingCount===1?'avaliação':'avaliações'}</small></div></div><div class="card earnings-card" style="display:flex;flex-direction:column;gap:.2rem;margin:.7rem 0"><small>Rendimento realizado</small><strong style="font-size:1.35rem">${earningsMoney(earnings)}</strong><small>${Number(earnings?.completedCount||0)} trabalho(s) ou negócio(s) concluído(s) e confirmado(s)</small></div>${u.bio?`<p>${esc(u.bio)}</p>`:''}${u.professions?.length?`<h4>Profissões</h4><p>${u.professions.map(esc).join(' · ')}</p>`:''}${u.skills?.length?`<h4>Competências</h4><p>${u.skills.map(esc).join(' · ')}</p>`:''}${u.experience?.length?`<h4>Experiência profissional</h4>${u.experience.map(x=>`<div class="row2"><span>${esc(x.role||x.title||x)}</span><small>${esc(x.company||x.period||'')}</small></div>`).join('')}`:''}${u.education?.length?`<h4>Formação</h4>${u.education.map(x=>`<div class="row2"><span>${esc(x.course||x.title||x)}</span><small>${esc(x.school||x.year||'')}</small></div>`).join('')}`:''}${u.portfolio?.length?`<h4>Portefólio</h4>${u.portfolio.map(x=>`<div class="card"><b>${esc(x.title||x.name||'Trabalho')}</b><p class="mut">${esc(x.description||'')}</p></div>`).join('')}`:''}<h4>Classificações</h4><p class="pr">${s.ratingCount?stars(Math.round(s.ratingAvg))+' '+s.ratingAvg.toFixed(1)+' de 5':'Ainda sem classificações'}</p>${s.ratingList.map(x=>`<div class="card"><b>${stars(x.stars)}</b><p>${esc(x.comment||'Sem comentário')}</p></div>`).join('')}${canRate&&u.cloudId&&S.me?.apiToken?`<button class="btn" data-a="rateRemote" data-id="${u.cloudId}">Classificar com estrelas</button>`:canRate&&!already?`<button class="btn" data-a="rate" data-id="${u.id}">Classificar este perfil</button>`:already?'<p class="mut">Já classificaste este perfil.</p>':!own?'<p class="mut">A classificação fica disponível depois de uma interação concluída entre vocês.</p>':''}<h4>Histórico</h4>${s.list.length?s.list.map(x=>`<div class="row2"><span>${esc(x.title)}</span><span class="${x.paid?'ok':'bad'}">${x.paid?'Pago':'Não pago'}</span></div>`).join(''):'<p class="mut">Ainda não há trabalhos concluídos com este utilizador.</p>'}<p class="mut" style="margin-top:1rem">Membro desde ${fmtMonth(u.at)}</p>${S.me&&!own?`<div class="share-actions"><button class="btn secondary" data-a="report" data-t="user" data-id="${u.id}" data-cid="${u.cloudId||''}">Denunciar perfil</button><button class="btn secondary" data-a="blockUser" data-id="${u.id}" data-cid="${u.cloudId||''}">Bloquear</button></div>`:''}`}

/* vistas */
const skel=()=>`<div class="top"><div class="sk" style="width:7rem;height:2rem"></div><div class="sk" style="width:5.5rem;height:2.5rem"></div></div><div class="main">${'<div class="skc"><div class="sk" style="height:10rem"></div><div class="sk" style="height:1.2rem;width:60%"></div><div class="sk" style="height:1rem;width:40%"></div><div class="sk" style="height:3rem;border-radius:999px"></div></div>'.repeat(2)}</div>`;
const fd=(l,i,t='text',p='',a='')=>{const field=`<input id="${i}" type="${t}" placeholder="${p}" ${a}>`;return `<div class="fd"><label for="${i}">${l}</label>${t==='password'?`<div class="pw-field">${field}<button type="button" class="pw-toggle" data-a="togglePassword" data-id="${i}" aria-label="Mostrar palavra-passe">${ic('eye')}</button></div>`:field}</div>`};
const GLOGO='<svg viewBox="0 0 48 48" aria-hidden="true"><path fill="#EA4335" d="M24 9.5c3.54 0 6.71 1.22 9.21 3.6l6.85-6.85C35.9 2.38 30.47 0 24 0 14.62 0 6.51 5.38 2.56 13.22l7.98 6.19C12.43 13.72 17.74 9.5 24 9.5z"/><path fill="#4285F4" d="M46.98 24.55c0-1.57-.15-3.09-.38-4.55H24v9.02h12.94c-.58 2.96-2.26 5.48-4.78 7.18l7.73 6c4.51-4.18 7.09-10.36 7.09-17.65z"/><path fill="#FBBC05" d="M10.53 28.59c-.48-1.45-.76-2.99-.76-4.59s.27-3.14.76-4.59l-7.98-6.19C.92 16.46 0 20.12 0 24c0 3.88.92 7.54 2.56 10.78l7.97-6.19z"/><path fill="#34A853" d="M24 48c6.48 0 11.93-2.13 15.89-5.81l-7.73-6c-2.15 1.45-4.92 2.3-8.16 2.3-6.26 0-11.57-4.22-13.47-9.91l-7.98 6.19C6.51 42.62 14.62 48 24 48z"/></svg>';
const googleBtn=`<p class="or">ou</p><div class="gbtn" id="gbtn"><button class="btn secondary" data-a="googleSetup">${GLOGO}Continuar com Google</button></div>`;
const auth=reg=>`<div class="auth"><h1 class="logo">${LOGO}</h1><h2 class="auth-title">${reg?'Junta-te ao Aquipay':'Acede à tua conta'}</h2><p class="err" id="err" role="alert"></p>${reg?fd('Nome','rn','text','','autocomplete="name"')+fd('Email','re','email','','autocomplete="email"')+fd('Palavra-passe','rp','password','Mínimo 10 caracteres','autocomplete="new-password"')+'<button class="btn" data-a="register">Criar conta</button>'+googleBtn+'<p class="sw">Já tens conta? <a class="link" data-a="toLogin">Entrar</a></p>':fd('Email','le','email','','autocomplete="username"')+fd('Palavra-passe','lp','password','','autocomplete="current-password"')+'<p class="sw" style="margin-top:-.2rem"><a class="link" data-a="forgot">Esqueceste-te da palavra-passe?</a></p><button class="btn" data-a="login">Entrar</button>'+googleBtn+'<p class="sw">Ainda não tens conta? <a class="link" data-a="toReg">Criar conta</a></p>'}<p class="sw"><a class="link" data-a="explore">Explorar perfis públicos</a></p><p class="legal-note">${T('Ao continuar, aceitas os {a} e a {b}.',{a:'<a class="link" data-a="openDoc" data-id="termos">'+T('Termos de Uso')+'</a>',b:'<a class="link" data-a="openDoc" data-id="privacidade">'+T('Política de Privacidade')+'</a>'})}</p></div>`;
async function loadGoogle(){if(window.google?.accounts?.id)return true;return new Promise(ok=>{const t=document.createElement('script');t.src='https://accounts.google.com/gsi/client';t.async=true;t.onload=()=>ok(true);t.onerror=()=>ok(false);document.head.appendChild(t)})}
async function initGoogle(){const box=$('gbtn');if(!box||!CFG.googleClientId)return;if(isNativeApp())return;if(!(await loadGoogle())||!window.google?.accounts?.id)return;const b=$('gbtn');if(!b)return;google.accounts.id.initialize({client_id:CFG.googleClientId,callback:googleDone,ux_mode:'popup',auto_select:false,cancel_on_tap_outside:true});b.innerHTML='';google.accounts.id.renderButton(b,{type:'standard',theme:document.documentElement.dataset.theme==='dark'?'filled_black':'outline',size:'large',shape:'pill',text:'continue_with',logo_alignment:'left',locale:GOOGLE_LOCALES[LANG],width:Math.min(Math.round(b.clientWidth)||320,400)})}
async function googleCredentialDone(credential){const fail=m=>{const r=$('err');r?r.textContent=m:toast(m)};try{if(S.securityReauth){S.securityReauth=false;return await A.beginTotpSetup({googleCredential:credential})}const res=await fetch(CFG.apiBase+'/api/auth/google',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({credential})});const cloud=await res.json().catch(()=>({}));if(!res.ok)return fail(cloud.error||'Não foi possível entrar com Google.');if(cloud.requiresTwoFactor&&cloud.challengeId){S.authChallenge=cloud.challengeId;S.authGoogle=true;render();return}if(!cloud.token||!cloud.user)return fail('Resposta de autenticação inválida.');await completeCloudLogin(cloud,true)}catch(e){fail(e?.message||'Não foi possível ligar ao servidor. Tenta novamente.')}}
async function googleDone(resp){return googleCredentialDone(resp?.credential)}
const bar=t=>`<header class="top"><button class="btn ic" data-a="back" aria-label="Fechar">${ic('x')}</button><h2>${t}</h2><span style="width:2.5rem"></span></header>`;
const searchBox=(id,ph,val,clr)=>`<div class="sf">${ic('search')}<input id="${id}" type="search" placeholder="${ph}" value="${esc(val||'')}" aria-label="${ph}" autocomplete="off" enterkeyhint="search"><button type="button" class="search-clear" data-a="${clr}" aria-label="Limpar pesquisa">${ic('x')}</button></div>`;
const empty=(a,b)=>`<div class="empty"><b>${a}</b>${b}</div>`;
 function networkCard(u){const prof=(()=>{try{return JSON.parse(u.professions_json||'[]')}catch{return[]}})();return `<article class="card network-card"><div class="ho">${u.avatar_url?`<img class="av" src="${CFG.apiBase+u.avatar_url}" alt="" loading="lazy">`:`<div class="av">${esc((u.name||'?').slice(0,2).toUpperCase())}</div>`}<div class="network-person"><b>${esc(u.name||'Profissional')}</b><small>${esc(prof.slice(0,3).join(' · ')||u.city||'Profissional no Aquipay')}</small><small>${Number(u.followers_count||0)} seguidores</small></div></div><div class="network-actions"><button class="btn secondary" data-a="viewProfile" data-id="${esc(u.id)}">Ver perfil</button><button class="btn ${u.is_following?'secondary':'network-follow'}" data-a="toggleFollow" data-id="${esc(u.id)}" data-following="${u.is_following?'1':'0'}">${u.is_following?'A seguir':'Seguir'}</button></div></article>`}
 const onboardingSteps=[
  {title:'Constrói um perfil profissional',description:'Apresenta as tuas competências, experiência e trabalhos. Um perfil completo ajuda clientes e empresas a reconhecerem o teu valor.',icon:'user'},
  {title:'Confirma a tua identidade',description:'Conclui a verificação de identidade para reforçar a autenticidade do teu perfil e transmitir mais confiança.',icon:'badge'},
  {title:'Dá visibilidade ao teu trabalho',description:'Cria anúncios de serviços, produtos ou oportunidades e chega a pessoas que procuram o que tens para oferecer.',icon:'plus'},
  {title:'Constrói a tua reputação',description:'Reúne avaliações reais, mantém o teu perfil atualizado e demonstra a qualidade do teu trabalho.',icon:'star'},
  {title:'Acompanha profissionais do teu ramo',description:'Segue especialistas e criadores da tua área para conhecer projetos, acompanhar publicações e descobrir novas referências.',icon:'share'},
  {title:'Amplia a tua rede de contactos',description:'Encontra pessoas pelo nome ou profissão, visita os seus perfis e cria ligações profissionais no AquiPay.',icon:'users'}
 ];
 function onboardingView(){const n=S.onboardingStep,step=onboardingSteps[n];return `${bar('Começa no AquiPay')}<main class="onboarding-page"><div class="onboarding-progress"><span>GUIA DE UTILIZAÇÃO</span><b>${n+1} / ${onboardingSteps.length}</b></div><div class="onboarding-track"><i style="width:${((n+1)/onboardingSteps.length)*100}%"></i></div><div class="onboard-art onboard-art-${n}"><img class="onboard-character" src="assets/onboarding-professional.jpg" alt="Personagem profissional do AquiPay"></div><div class="onboard-copy"><small>PASSO ${String(n+1).padStart(2,'0')}</small><h1>${step.title}</h1><p>${step.description}</p></div><div class="onboard-controls"><button class="btn secondary" data-a="onboardSkip">Pular</button><button class="btn" data-a="onboardNext">${n===onboardingSteps.length-1?'Começar a explorar':'Próximo'}</button></div></main>`}
 function networkView(){return `${bar('Rede profissional')}<main class="pad network-page"><p class="mut">Descobre profissionais, acompanha o trabalho de quem admiras e amplia a tua rede.</p><div class="network-search">${searchBox('networkSearch','Pesquisar por nome, profissão ou cidade','','clearNetworkSearch')}</div><div class="network-shortcuts"><button class="btn secondary" data-a="loadNetwork">Descobrir profissionais</button><button class="btn secondary" data-a="loadFollowing">A quem sigo</button></div><section class="contacts-invite"><div><b>Encontra quem já conheces</b><p class="mut">Descobre quais dos teus contactos já estão no AquiPay.</p></div><button class="btn" data-a="findContacts">Encontrar contactos</button><small>Os números são usados apenas para procurar correspondências e não ficam guardados.</small></section><h4 id="networkHeading">Profissionais para conhecer</h4><div id="networkResults">${S.networkUsers.length?S.networkUsers.map(networkCard).join(''):empty('A tua rede começa aqui','Pesquisa profissionais do teu ramo ou descobre novos perfis para acompanhar.')}</div></main>`}
const pics=f=>f&&f.length?`<div class="ph">${f.map(b=>`<img src="${typeof b==='string'?esc(b):src(b)}" alt="Foto do anúncio" loading="lazy">`).join('')}</div>`:'';
function card(v){const o=U(v.ownerId)||{id:v.ownerId,nome:'Utilizador'},mine=S.me.id===v.ownerId,done=S.cands.some(c=>c.vagaId===v.id&&c.userId===S.me.id),negotiated=!!(v.negotiated||S.cands.some(c=>c.vagaId===v.id&&c.status==='aceite')),rating=stats(o.id),ratingCount=rating.ratingCount||Number(v.ownerRatingCount||0),ratingAvg=rating.ratingCount?rating.ratingAvg:Number(v.ownerRatingAvg||0),ratingLabel=ratingCount?`${ratingAvg.toFixed(1)} (${ratingCount})`:'Sem classificações',published=Number(v.at)?new Date(v.at).toLocaleString('pt-AO',{dateStyle:'short',timeStyle:'short'}):'Data indisponível';return`<article class="card post-card"><div class="post-head"><div class="ho post-author">${av(o,44)}<div style="flex:1;min-width:0"><b>${esc(o.nome)}</b> ${o.verified?ic('badge','ok s'):''}<small>Publicado em ${esc(published)}</small></div></div><button class="post-more" data-a="postMenu" data-id="${v.id}" aria-label="Mais opções">${ic('more')}</button></div><h3 class="post-title">${esc(v.titulo)}</h3><div class="post-meta"><span class="pill">${T(TIPO[v.tipo])}</span><span class="pill">${esc(COUNTRY_LABELS.of(v.country||'AO')||'Angola')}</span></div><p class="pr">${v.preco?kz(v.preco,v.currency||'AOA'):'A combinar'}</p>${pics(v.fotos)}${v.desc?`<p class="post-description">${esc(v.desc)}</p>`:''}<div class="post-rating"><span>${ic('star','fill star s')} ${ratingCount?ratingLabel:'Ainda sem avaliações'}</span><button class="link" data-a="viewProfile" data-id="${o.cloudId||o.id}">Ver perfil e avaliações</button></div>${negotiated?'<div class="mine-actions"><span class="pill">NEGOCIADO</span><span class="mut">O proprietário já aceitou uma proposta. Não são necessárias novas candidaturas.</span></div>':mine?'<div class="mine-actions"><span class="pill">O teu anúncio</span><button class="btn secondary danger-outline" data-a="askDeleteListing" data-id="'+v.id+'">Eliminar</button></div>':`<button class="btn post-proposal" data-a="apply" data-id="${v.id}" ${done?'disabled':''}>${done?'Proposta enviada':'Apresentar proposta'}</button>`}</article>`}
const ST={enviada:'Enviada',aceite:'Aceite',concluida:'Concluída',recusada:'Recusada',cancelada:'Cancelada',pago:'Pagamento confirmado',nao_pago:'Pagamento não recebido'};
function candCard(c){const v=S.vagas.find(x=>x.id===c.vagaId)||{titulo:'Anúncio removido'};const confirmClient=c.status==='aceite'&&v.tipo!=='biscato';return`<div class="card"><h3>${esc(v.titulo)}</h3><p class="mut">${ago(c.at)} · ${c.spent?T('-{n} créditos',{n:c.spent}):T('sem custo')}</p><p style="margin:.5rem 0"><span class="pill">${ST[c.status]}</span></p>${confirmClient?`<button class="btn" data-a="step" data-id="${c.id}" data-v="concluida">Confirmar trabalho concluído</button>`:''}${c.status==='concluida'?`<div class="stack"><button class="btn" data-a="paid" data-id="${c.id}" data-v="1">Recebi o pagamento</button><button class="btn" data-a="paid" data-id="${c.id}" data-v="0">Não recebi</button></div>`:''}</div>`}
function mineCard(v){const n=S.cands.filter(c=>c.vagaId===v.id).length;return`<div class="card"><h3>${esc(v.titulo)}</h3><p class="mut">${n} candidatura${n===1?'':'s'}</p><div class="mine-actions"><button class="btn" data-a="cands" data-id="${v.id}">Ver candidatos</button><button class="btn secondary danger-outline" data-a="askDeleteListing" data-id="${v.id}">Eliminar anúncio</button></div></div>`}
function feed(){if(S.tab==='vagas'){const q=norm(S.searchText);const l=S.vagas.filter(v=>v.status==='ativa'&&!isBlocked(U(v.ownerId))&&(S.st.feedCountry==='all'||(v.country||'AO')===(S.st.feedCountry||'AO'))&&(!q||norm([v.titulo,v.desc,v.local,T(TIPO[v.tipo]),U(v.ownerId)?.nome].join(' ')).includes(q))).sort((a,b)=>b.at-a.at);const people=q?S.users.filter(u=>u.id!==S.me.id&&!isBlocked(u)&&norm([u.nome,u.cidade,u.bio,(u.professions||[]).join(' ')].join(' ')).includes(q)):[];const peopleHtml=people.length?`<h4>Perfis encontrados</h4>${people.slice(0,12).map(u=>`<div class="card ho">${av(u,42)}<div style="flex:1"><b>${esc(u.nome)}</b><small>${esc(u.cidade||'')} · ${(u.professions||[]).map(esc).join(', ')}</small></div><button class="btn secondary" style="width:auto" data-a="viewProfile" data-id="${u.id}">Ver perfil</button></div>`).join('')}`:'';return (l.length?l.map(card).join(''):empty('Sem anúncios por enquanto','Esta área ainda não tem publicações. Cria o primeiro anúncio e dá visibilidade à tua oportunidade.'))+peopleHtml}
if(S.tab==='cand'){const l=S.cands.filter(c=>c.userId===S.me.id).sort((a,b)=>b.at-a.at);return l.length?l.map(candCard).join(''):empty('Ainda sem candidaturas','As propostas que apresentares ficarão reunidas nesta área.')}
const l=S.vagas.filter(v=>v.ownerId===S.me.id).sort((a,b)=>b.at-a.at);return l.length?l.map(mineCard).join(''):empty('Ainda não publicaste anúncios','Os anúncios que criares serão apresentados aqui, para acompanhares as respostas num só lugar.')}
function home(){const n=unread(),m=unreadMessages();return`<main class="main home-scroll" id="homeScroll"><div class="search-top">${searchBox('globalSearch','Pesquisar oportunidades, serviços e profissionais',S.searchText,'clearSearch')}<button class="btn ic filter-trigger" data-a="countryFilter" aria-label="Filtrar por país">${ic('filter')}${S.st.feedCountry&&S.st.feedCountry!=='all'?'<span class="filter-dot"></span>':''}</button><button class="btn ic add" data-a="pub" aria-label="Criar anúncio">${ic('plus')}</button></div><header class="top"><h1 class="logo">${LOGO}</h1><div class="row"><button class="btn ic" data-a="nt" aria-label="Notificações">${ic('bell')}${n?`<span class="bdg">${n>99?'99+':n}</span>`:''}</button><button class="btn ic" data-a="messages" aria-label="Mensagens">${ic('message')}${m?`<span class="bdg">${m>99?'99+':m}</span>`:''}</button><button class="btn ic" data-a="menu" aria-label="Menu">${av(S.me,28).replace('background:var(--in)','background:transparent')}</button></div></header><nav class="tabs">${[['vagas','Oportunidades'],['cand','Candidaturas'],['mine','Os meus anúncios'],['network','Rede profissional']].map(([k,l])=>`<button class="tab ${S.tab===k?'on':''}" data-a="tab" data-id="${k}">${l}</button>`).join('')}</nav><div id="feed">${feed()}</div></main>`}
