const kv=(a,b)=>`<div class="kv"><span>${a}</span><small>${esc(b)}</small></div>`;
const notifState=()=>isNativeApp()&&nativePushPlugin()?'Notificações nativas do Android.':!('Notification'in window)?'Este dispositivo não suporta notificações.':Notification.permission==='granted'?'Notificações ativas neste dispositivo.':Notification.permission==='denied'?'Bloqueadas nas definições do navegador.':'Ativa as notificações para receber mensagens, candidaturas e novos trabalhos.';
const legalList=()=>DOC_ORDER.map(([g,ids])=>`<h4>${g}</h4><div class="menu">${ids.map(id=>`<button class="mi" data-a="openDoc" data-id="${id}">${ic(DOCS[id].icon)}<span>${DOCS[id].title}</span></button>`).join('')}</div>`).join('');
const DOC_SLUGS={termos:'termos-de-uso',privacidade:'politica-de-privacidade',reembolso:'pagamentos-e-reembolsos',cookies:'cookies-e-armazenamento',conduta:'regras-da-comunidade',seguranca:'dicas-de-seguranca',faqs:'perguntas-frequentes',ajuda:'ajuda-e-contacto',sobre:'sobre-o-aquipay'};
const DOC_ROUTE=Object.fromEntries(Object.entries(DOC_SLUGS).map(([id,slug])=>[slug,id]));
const docUrl=id=>'/'+(DOC_SLUGS[id]||id);
const BACK={chat:'messages',proposal:'home',set:'home',legal:()=>S.legalFrom||'home',doc:()=>S.me?'legal':'home'};
function chatView(){const c=S.activeChat||{};return`<main class="full-page chat-page"><header class="top"><button class="btn ic" data-a="back" aria-label="Voltar">${ic('x')}</button><h2>${esc(c.name||'Conversa')}</h2><div class="call-head-actions"><button class="btn ic" data-a="startCall" data-type="voice" aria-label="Chamada de voz">${ic('phone')}</button><button class="btn ic" data-a="startCall" data-type="video" aria-label="Chamada de vídeo">${ic('video')}</button></div></header><div class="chat-messages full-chat-messages" id="chatMessages">${A.chatMessagesHtml(c.rows||[])}</div><div class="chat-compose"><textarea id="chatText" maxlength="4000" placeholder="Escreve a tua mensagem"></textarea><button class="btn" data-a="sendChatMessage" data-id="${esc(c.id||'')}" data-name="${esc(c.name||'Conversa')}">Enviar</button></div></main>`}
function proposalView(){const p=S.activeProposal||{};return`<main class="full-page proposal-page"><header class="top"><button class="btn ic" data-a="back" aria-label="Voltar">${ic('x')}</button><h2>Enviar proposta</h2><span></span></header><div class="pad stack"><h3>${esc(p.title||'Oportunidade')}</h3><p class="mut">Apresenta-te e explica como vais realizar este trabalho.</p><div class="fd"><label for="proposalMessage">A tua mensagem e proposta</label><textarea id="proposalMessage" maxlength="1500" placeholder="Apresenta a tua experiência, prazo e valor proposto…">Tenho interesse nesta oportunidade e gostaria de apresentar a minha proposta.</textarea></div>${fd('Valor proposto ('+(p.currency||'AOA')+', opcional)','proposalPrice','number','Ex.: 25000','min="0" step="0.01" inputmode="decimal"')}<p class="mut">${p.plus?'Candidaturas ilimitadas incluídas no Plus.':`${Math.max(0,5-(p.used||0))} candidaturas gratuitas restantes hoje.`}</p><button class="btn" data-a="send" data-id="${esc(p.id||'')}">Enviar proposta</button></div></main>`}
const views={home,chat:chatView,proposal:proposalView,network:networkView,onboarding:onboardingView,reset:()=>`<div class="auth"><h1 class="logo">${LOGO}</h1><h2 style="text-align:center">Nova palavra-passe</h2><p class="err" id="err" role="alert"></p>${fd('Nova palavra-passe','rp','password','Mínimo 10 caracteres','autocomplete="new-password"')}${fd('Repete a nova palavra-passe','rp2','password','','autocomplete="new-password"')}${fd('Código do autenticador (se ativado)','rp2fa','text','Código de 6 dígitos ou recuperação','inputmode="text"')}<button class="btn" data-a="doReset">Guardar palavra-passe</button><p class="sw"><a class="link" data-a="toLogin">Voltar a entrar</a></p></div>`,explore:()=>`${bar('Conhecer profissionais')}<div class="pad stack">${searchBox('publicSearch','Nome, profissão ou cidade','','clearPublic')}<div id="publicResults"><p class="mut">Pesquisa profissionais sem precisares de iniciar sessão.</p></div><a class="link" data-a="toLogin">Entrar no Aquipay</a></div>`,
pub:()=>`${bar('Novo anúncio')}<div class="pad stack"><p class="mut">Plano Free: ${Math.max(0,10-(S.usage?.postsThisMonth??localPostsThisMonth()))} de 10 anúncios gratuitos restantes este mês. O Plus permite publicar sem limite.</p>${fd('Título','pt','text','Ex.: Montagem de móveis')}${sel('ptipo','Tipo',Object.entries(TIPO),'biscato')}${fd('Preço (moeda do país do anúncio, opcional)','pp','number','8000','inputmode="numeric"')}${sel('País do anúncio','pcountry',countryOptions(),'AO')}${fd('Cidade (opcional)','pl','text','Ex.: Luanda, Talatona')}<div class="fd"><label for="pd">Descrição</label><textarea id="pd" placeholder="Explica claramente o que procuras, as condições e os requisitos"></textarea></div><div><button class="btn" data-a="addpic">${ic('image')} Adicionar fotos</button><div class="thumbs" id="th"></div></div><button class="btn" data-a="publish">Publicar</button></div>`,
coins:()=>`${bar('Créditos e plano')}<div class="pad"><div class="bal"><b>${S.me.coins||0}</b>créditos${hasPlus(S.me)?`<p class="ok">Plus ativo</p>`:''}</div><h4>Plano Free</h4><div class="card"><p class="mut">5 candidaturas gratuitas por dia e 10 anúncios gratuitos por mês.</p><p class="mut">Utilização atual: ${S.usage?.applicationsToday??localApplicationsToday()}/5 candidaturas hoje · ${S.usage?.postsThisMonth??localPostsThisMonth()}/10 anúncios este mês.</p></div><h4>Plano Plus</h4><div class="card"><h3>Plus · $20/mês</h3><p class="mut" style="margin:.3rem 0 .8rem">Candidaturas e anúncios ilimitados, sem gastar créditos.</p><button class="btn" data-a="checkout" data-id="plus">Ativar Plus</button></div><h4>Comprar créditos</h4>${PKG.map(p=>`<div class="card row2" style="align-items:center"><div><b>${p[0]} créditos</b>${p[2]?`<small style="display:block">+${p[2]} de bónus</small>`:''}</div><button class="btn" style="width:auto" data-a="checkout" data-id="${p[0]}">${p[1]}</button></div>`).join('')}</div>`,
me:()=>{const u=S.me;return`${bar('Perfil')}<div class="pad stack"><div class="pf">${av(u,88)}<button class="btn" style="width:auto" data-a="addavatar">${ic('image')} Alterar foto</button></div>${fd('Nome','mn','text','',`value="${esc(u.nome)}"`)}${fd('Cidade','mc','text','Ex.: Luanda',`value="${esc(u.cidade||'')}"`)}${fd('Telefone','mt','tel','',`value="${esc(u.tel||'')}"`)}<div class="fd"><label for="mb">Biografia</label><textarea id="mb">${esc(u.bio||'')}</textarea></div>${fd('Profissões (separadas por vírgula)','mprof','text','Ex.: Electricista, Técnico de informática',`value="${esc((u.professions||[]).join(', '))}"`)}${fd('Competências (separadas por vírgula)','mskills','text','Ex.: Excel, soldadura, atendimento',`value="${esc((u.skills||[]).join(', '))}"`)}<div class="fd"><label for="mexp">Experiência profissional (uma por linha)</label><textarea id="mexp" placeholder="Cargo | Empresa | Período">${esc((u.experience||[]).map(x=>[x.role||x.title||'',x.company||'',x.period||''].join(' | ')).join('\n'))}</textarea></div><div class="fd"><label for="medu">Formação (uma por linha)</label><textarea id="medu" placeholder="Curso | Instituição | Ano">${esc((u.education||[]).map(x=>[x.course||x.title||'',x.school||'',x.year||''].join(' | ')).join('\n'))}</textarea></div><div class="fd"><label for="mport">Portefólio (um projeto por linha)</label><textarea id="mport" placeholder="Projeto | Descrição">${esc((u.portfolio||[]).map(x=>[x.title||x.name||'',x.description||''].join(' | ')).join('\n'))}</textarea></div><div class="fd"><label for="mpublic">Perfil público</label><select id="mpublic"><option value="true" ${u.publicProfile!==false?'selected':''}>Qualquer pessoa pode encontrar e ver o perfil</option><option value="false" ${u.publicProfile===false?'selected':''}>Perfil privado</option></select></div><button class="btn" data-a="saveme">Guardar perfil</button><button class="btn secondary" data-a="shareProfile">Partilhar perfil</button><button class="btn secondary" data-a="copyProfile">Copiar link do perfil</button><h4>Documentos e portefólio</h4><p class="mut">Envia CV, certificados, trabalhos e vídeo. Escolhe se cada ficheiro pode aparecer no perfil público.</p>${sel('doccat','Tipo de ficheiro',[['cv','CV / Currículo'],['certificate','Certificado'],['portfolio','Portefólio'],['experience','Experiência profissional'],['education','Formação académica'],['intro_video','Vídeo de apresentação']],'cv')}<div class="fd"><label for="docpublic">Visibilidade do ficheiro</label><select id="docpublic"><option value="false" selected>Privado</option><option value="true">Visível no perfil público</option></select></div><button class="btn secondary" data-a="addDocument">Escolher ficheiro no dispositivo</button>${S.documents.map(d=>`<div class="row2 card"><span>${esc(d.original_name)}<small>${d.is_public?'Visível no perfil':'Privado'}</small></span><button class="btn secondary" style="width:auto" data-a="deleteDocument" data-id="${d.id}">Apagar</button></div>`).join('')}<h4>Verificação de identidade</h4><p class="mut">${u.identityVerified?'A tua identidade foi confirmada através do Bilhete de Identidade.':'Confirma a tua identidade com o Bilhete de Identidade para aumentar a confiança no teu perfil.'}</p>${u.identityVerified?'':'<button class="btn" data-a="openIdentity">Verificar identidade com BI</button>'}</div>`},
set:()=>{const u=S.me,n=S.st.notif||{};return`${bar('Definições')}<div class="pad stack"><h4>Conta</h4><div class="group">${kv('Nome',u.nome)}${kv('Email',u.email||'—')}</div><div class="menu"><button class="mi" data-a="open" data-id="me">${ic('user')}<span>Editar perfil e documentos</span></button><button class="mi" data-a="open" data-id="coins">${ic('coins')}<span>Créditos e plano</span></button></div>${isNativeApp()?`<h4>Google Play</h4><div class="menu"><button class="mi" data-a="requestPlayReview"><span>Avaliar o AquiPay na Play Store</span></button></div>`:``}<h4>País e moeda</h4><p class="mut">Os preços e rendimentos serão apresentados na moeda do país escolhido. A conversão é indicativa.</p>${sel('profileCountry','País do perfil',countryOptions(),S.st.profileCountry||'AO')}${sel('profileCurrency','Moeda de apresentação',currencySelectOptions(),S.st.currency||'AOA')}<div class="row"><button class="btn secondary" data-a="autoCurrency">Usar moeda do país</button><button class="btn" data-a="saveCurrency">Guardar</button></div>${settingsAnchor}${sel('lang','Idioma',LANGS.map(([c,,n])=>[c,n]),LANG)}${sel('theme','Tema',[['dark','Escuro'],['light','Claro']],S.st.theme)}${sel('font','Tipo de letra',[['padrao','Padrão'],['redonda','Arredondada'],['classica','Clássica']],S.st.font)}${sel('size','Tamanho da letra',[[90,'Pequeno'],[100,'Normal'],[115,'Grande'],[130,'Muito grande']],S.st.size)}${sel('motion','Animações',[['auto','Normais'],['reduzida','Reduzidas']],S.st.motion)}<h4>Feedback ao tocar</h4><div class="group">${tg('feedback.sound','Som dos botões','Som discreto ao tocar e ao receber confirmações',S.st.feedback?.sound!==false)}${tg('feedback.haptics','Vibração dos botões','Vibração leve ao tocar nos controlos',S.st.feedback?.haptics!==false)}</div><h4>Notificações</h4><p class="mut">${notifState()}</p>${(isNativeApp()&&nativePushPlugin())||('Notification'in window&&Notification.permission==='default')?'<button class="btn" data-a="push">Ativar notificações</button>':''}<div class="group">${tg('notif.candidaturas','Candidaturas','Quando alguém se candidata ou responde a uma candidatura',n.candidaturas!==false)}${tg('notif.pagamentos','Pagamentos','Confirmações de pagamento dos trabalhos',n.pagamentos!==false)}${tg('notif.novidades','Novos trabalhos e publicações','Quando alguém publicar um novo trabalho, produto ou serviço',!!n.novidades)}</div><h4>Conector de IA (MCP)</h4><p class="mut">Liga o AquiPay a uma IA compatível. A IA só terá acesso aos dados que autorizares.</p><div class="group"><div class="row" style="align-items:center;gap:.6rem"><code style="font-size:12px;overflow-wrap:anywhere;flex:1">https://aquipay-api.osamariches.workers.dev/mcp</code><button class="btn secondary" style="width:auto" data-a="copyMcpUrl">Copiar</button></div><button class="btn secondary" data-a="loadMcpConnections">Ver aplicações ligadas</button><div id="mcpConnections"></div></div><h4>Privacidade</h4><div class="group">${tg('publicProfile','Perfil público','Qualquer pessoa pode encontrar e ver o teu perfil',u.publicProfile!==false)}</div><h4>Dados e armazenamento</h4>${sel('saver','Qualidade das fotografias',[['off','Alta'],['on','Poupar dados']],S.st.saver)}<div class="menu"><button class="mi" data-a="exportData">${ic('archive')}<span>Exportar os meus dados</span></button><button class="mi" data-a="askClear">${ic('trash')}<span>Limpar dados deste dispositivo</span></button></div><h4>Segurança e privacidade</h4><div class="menu"><button class="mi" data-a="openIdentity">${ic('badge')}<span>Verificação de identidade com BI</span></button><button class="mi" data-a="openSecurity">${ic('shield')}<span>Segurança da conta, 2FA e dispositivos</span></button>${u.google?'':`<button class="mi" data-a="askPassword">${ic('lock')}<span>Alterar palavra-passe</span></button>`}<button class="mi" data-a="blockedList">${ic('shield')}<span>Utilizadores bloqueados</span></button><button class="mi" data-a="logout">${ic('logout')}<span>Terminar sessão</span></button><button class="mi bad" data-a="askDelete">${ic('trash')}<span>Eliminar a minha conta</span></button></div><h4>Legal e ajuda</h4><div class="menu"><button class="mi" data-a="open" data-id="legal">${ic('file')}<span>Termos, privacidade e ajuda</span></button></div><p class="legal-note" style="margin-top:1rem;font-weight:700;letter-spacing:.08em">ISAB GROUP</p></div>`},
identity:()=>{
 const q=S.identityStatus||{status:'Not Started',canStart:true};
 const labels={'Not Started':'Não iniciada','In Progress':'Em andamento','Awaiting User':'A aguardar a tua ação','In Review':'Em análise','Resubmitted':'Reenviada','Approved':'Identidade verificada','Declined':'Não aprovada','Expired':'Expirada','Not Finished':'Não concluída','Abandoned':'Abandonada','Kyc Expired':'Verificação expirada'};
 const good=q.verified||q.status==='Approved',active=!!q.sessionUrl&&!good;
 return `${bar('Verificação de identidade')}<div class="pad stack"><div class="card"><b>Confirma a tua identidade</b><p class="mut">Verifica a tua conta AquiPay com o Bilhete de Identidade angolano. A verificação é realizada pela Didit, que poderá solicitar fotografias do documento, uma selfie e uma prova de vida.</p><p class="${good?'ok':'mut'}">${good?'Identidade confirmada':esc(labels[q.status]||q.status||'Não iniciada')}</p>${q.verifiedAt?'<small>Verificada em '+esc(new Date(q.verifiedAt).toLocaleDateString('pt-AO'))+'</small>':''}</div>${good?'':active?'<div class="card"><p class="mut">Tens uma verificação em curso. Podes continuar onde paraste.</p><button class="btn" data-a="resumeIdentity">Continuar verificação</button></div>':`<div class="card"><b>Consentimento e privacidade</b><p class="mut">Ao continuar, autorizo o AquiPay a partilhar com a Didit os dados necessários para confirmar a minha identidade, incluindo imagens do BI e dados biométricos (selfie e prova de vida). Compreendo que a Didit é um prestador externo de verificação e que esta operação será usada para segurança e prevenção de fraude.</p><label class="checkline"><input id="identityConsent" type="checkbox"> Li e aceito o tratamento dos meus dados para esta verificação.</label><button class="btn" data-a="startIdentity">Iniciar verificação</button></div>`}${!good?'<button class="btn secondary" data-a="refreshIdentity">Atualizar estado</button>':''}<p class="mut">Não envies o teu BI por mensagens ou email. A captura do documento deve acontecer apenas no fluxo seguro da Didit.</p></div>`
},
security:()=>{
 const q=S.securityStatus||{twoFactorEnabled:false,sessions:[]};
 const bioButton=!isNativeApp()?'<p class="mut">Disponível apenas na aplicação Android instalada.</p>':(S.biometricEnabled?'<button class="btn danger" data-a="toggleBiometric">Desativar bloqueio biométrico</button>':'<button class="btn" data-a="toggleBiometric"'+((S.biometricInfo?.isAvailable||S.biometricInfo?.deviceIsSecure)?'':' disabled')+'>Ativar bloqueio biométrico</button>');
 const sessionRows=(q.sessions||[]).map(x=>'<div class="row2"><span><b>'+(x.current?'Este dispositivo':'Sessão ativa')+'</b><small>'+esc(new Date(x.createdAt).toLocaleString('pt-AO'))+'</small></span>'+(x.current?'<span class="pill">Atual</span>':'<button class="btn secondary" style="width:auto" data-a="revokeSession" data-id="'+esc(x.id)+'">Terminar</button>')+'</div>').join('');
 return `${bar('Segurança da conta')}<div class="pad stack"><div class="card"><b>Verificação em dois passos</b><p class="mut">Usa o Google Authenticator ou outra aplicação compatível com códigos TOTP para confirmar os acessos.</p><p class="${q.twoFactorEnabled?'ok':'mut'}">${q.twoFactorEnabled?'Ativa':'Desativada'}</p>${q.twoFactorEnabled?'<button class="btn secondary" data-a="regenerateRecovery">Gerar novos códigos de recuperação</button><button class="btn danger" data-a="disableTotp">Desativar verificação em dois passos</button>':'<button class="btn" data-a="setupTotp">Configurar Google Authenticator</button>'}</div><div class="card"><b>Bloqueio biométrico</b><p class="mut">Protege a abertura do AquiPay com impressão digital, reconhecimento facial compatível ou PIN do dispositivo. O token da sessão fica guardado no armazenamento seguro do Android.</p><p class="${S.biometricEnabled?'ok':'mut'}">${S.biometricEnabled?'Ativo neste dispositivo':(S.biometricInfo?.isAvailable||S.biometricInfo?.deviceIsSecure?'Disponível para ativar':'Não disponível neste dispositivo')}</p>${bioButton}</div><div class="card"><b>Dispositivos e sessões</b><p class="mut">Sessões ativas: ${q.sessions?.length||0}. Se não reconheceres um acesso, termina essa sessão.</p><button class="btn secondary" data-a="revokeOthers">Terminar todas as outras sessões</button>${sessionRows}</div><p class="mut">As novas sessões expiram após 7 dias. Protege também o email associado à tua conta e nunca partilhes códigos de verificação.</p><button class="btn secondary" data-a="refreshSecurity">Atualizar estado</button></div>`
},
legal:()=>`${bar('Legal e ajuda')}<div class="pad">${legalList()}</div>`,
doc:()=>`${bar('')}<div class="pad">${docHtml(S.doc)}</div>`,
notfound:()=>`<main class="notfound"><div class="nf-mark">${LOGO}</div><div class="nf-code">404</div><h1>Esta página não existe</h1><p>O endereço que tentaste abrir pode estar incorreto ou a página foi removida.</p><button class="btn" data-a="toLogin">Voltar ao início</button><a class="nf-link" href="/">Ir para a página inicial</a></main>`,
nt:()=>{const l=S.notifs.filter(n=>n.uid===S.me.id).sort((a,b)=>b.at-a.at);return`${bar('Notificações')}<div class="pad">${l.length?l.map(n=>`<div class="card"><p>${esc(n.txt)}</p><small>${ago(n.at)}</small></div>`).join(''):empty('Tudo em dia','As atualizações importantes da tua conta serão apresentadas aqui.')}</div>`},messages:()=>{const rows=S.conversations||[];return`${bar('Mensagens')}<div class="pad">${rows.length?rows.map(c=>{const unread=Number(c.unread_count||0)>0;return`<div class="card chat-row ${unread?'chat-unread':''}"><button class="chat-open" data-a="openConversation" data-id="${c.id}" data-name="${esc(c.other_user_name||'Conversa')}"><div class="av">${esc((c.other_user_name||'?').slice(0,2).toUpperCase())}</div><div class="chat-row-copy"><b>${esc(c.other_user_name||'Utilizador')}</b><small>${esc(c.last_message||'Proposta recebida')}</small><span class="chat-read-state">${unread?'Não lida':'Lida'}</span></div></button><button class="chat-mark" data-a="markConversation" data-id="${c.id}" data-unread="${unread?'1':'0'}">${unread?'Marcar como lida':'Marcar como não lida'}</button></div>`}).join(''):empty('A tua caixa de mensagens está vazia','Quando apresentares ou receberes uma proposta, a conversa ficará disponível aqui.')}</div>`}};
function deletionView(){const due=S.me?.deletionDueAt?new Date(S.me.deletionDueAt).toLocaleDateString('pt-AO'):'dentro de 30 dias';return `<div class="auth"><h1 class="logo">${LOGO}</h1><h2>Pedido de eliminação ativo</h2><p class="mut" style="margin:1rem 0">A tua conta está desativada e deixará de aparecer no Aquipay. Os dados serão eliminados permanentemente em ${esc(due)}. Podes cancelar o pedido antes dessa data.</p><div class="stack"><button class="btn" data-a="cancelDeletion">Cancelar pedido de eliminação</button><button class="btn secondary" data-a="logout">Terminar sessão</button></div></div>`}
function biometricLockView(){return `<div class="auth"><h1 class="logo">${LOGO}</h1><h2 style="text-align:center">AquiPay bloqueado</h2><p class="mut">Confirma a tua identidade para voltar a aceder à tua conta.</p><button class="btn" data-a="unlockApp">Desbloquear com biometria</button></div>`}
function twoFactorLoginView(){return `<div class="auth"><h1 class="logo">${LOGO}</h1><h2 style="text-align:center">Verificação em dois passos</h2><p class="mut">Introduz o código de 6 dígitos do Google Authenticator. Também podes usar um código de recuperação.</p><p class="err" id="login2faErr" role="alert"></p><input id="login2fa" inputmode="numeric" autocomplete="one-time-code" placeholder="Código de segurança" maxlength="20"><button class="btn" data-a="verifyLogin2fa">Confirmar acesso</button><button class="btn secondary" data-a="cancelLogin2fa">Voltar ao início</button></div>`}
async function completeCloudLogin(cloud,isGoogle=false){const email=String(cloud.user.email||'').toLowerCase();let u=S.users.find(x=>x.cloudId===cloud.user.id)||S.users.find(x=>x.email===email),isNew=false;if(!u){isNew=true;u={id:nid(),nome:cloud.user.name||email.split('@')[0],email,publicProfile:true,coins:10,plusUntil:null,daily:{date:day(),count:0},at:Date.now()};S.users.push(u)}u.apiToken=cloud.token;u.cloudId=cloud.user.id;u.nome=cloud.user.name;u.email=email;if(isGoogle)u.google=true;delete u.pw;u.deletionRequestedAt=cloud.user.deletionRequestedAt||null;u.deletionDueAt=cloud.user.deletionDueAt||null;await saveUser(u);if(!S.users.some(x=>x.id===u.id))S.users.push(u);S.authGoogle=false;await enter(u);if(isNew)notify(u.id,'A tua conta Aquipay está ativa. Recebeste 10 créditos de boas-vindas.','novidades')}
function render(){const a=$('app');if(!S.ready){a.innerHTML=skel();return}const L=langbar();if(S.biometricLocked){a.innerHTML=L+biometricLockView();return}if(S.shared){a.innerHTML=L+sharedView(S.shared);return}if(S.me&&S.onboarding){a.innerHTML=L+views.onboarding();return}if(S.me?.deletionRequestedAt){a.innerHTML=L+deletionView();return}if(!S.me||S.v==='reset'){if(S.authChallenge){a.innerHTML=L+twoFactorLoginView();return}const pub=['explore','doc','reset','notfound'].includes(S.v);a.innerHTML=L+(pub?views[S.v]():auth(S.v==='reg'));if(!pub)initGoogle();return}a.innerHTML=L+(views[S.v]||home)();if(S.v==='pub'){restoreListingDraft();thumbs()}}
const go=v=>{if(v!==S.v){S.navStack=S.navStack||[];S.navStack.push(S.v);if(S.navStack.length>30)S.navStack.shift()}S.v=v;render()};
function restoreListingDraft(){const d=S.listingDraft||{};for(const [id,key] of [['pt','title'],['pp','price'],['pl','city'],['pd','description']]){const el=$(id);if(el&&d[key]!=null)el.value=d[key]}for(const [id,key] of [['ptipo','kind'],['pcountry','country']]){const el=$(id);if(el&&d[key])el.value=d[key]}}
function persistListingDraft(){if(S.v!=='pub')return;const d={title:$('pt')?.value||'',price:$('pp')?.value||'',city:$('pl')?.value||'',description:$('pd')?.value||'',kind:$('ptipo')?.value||'biscato',country:$('pcountry')?.value||'AO'};S.listingDraft=d;try{sessionStorage.setItem('aquipay-listing-draft',JSON.stringify(d))}catch{}}
function clearListingDraft(){S.listingDraft={};try{sessionStorage.removeItem('aquipay-listing-draft')}catch{}}
