async verifyLogin2fa(){const code=$('login2fa')?.value.trim(),err=$('login2faErr');if(!code){if(err)err.textContent='Introduz o código do autenticador.';return}try{const res=await fetch(CFG.apiBase+'/api/auth/2fa/verify',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({challengeId:S.authChallenge,code})}),d=await res.json().catch(()=>({}));if(!res.ok)throw new Error(d.error||'Código inválido.');S.authChallenge=null;await completeCloudLogin(d,S.authGoogle)}catch(e){if(err)err.textContent=e.message}},
