async googleSetup(){if(isNativeApp()){try{const native=window.AquipayNativeGoogle;if(!native?.login)throw new Error('O início de sessão nativo ainda não foi carregado. Atualiza a aplicação.');const credential=await native.login(CFG.googleClientId);if(!credential||typeof credential!=='string')throw new Error('O Google não devolveu uma credencial válida.');await googleCredentialDone(credential)}catch(e){const code=String(e?.code||'').toUpperCase(),message=String(e?.message||'').trim();if(['USER_CANCELLED','USER_CANCELED','SIGN_IN_CANCELLED','SIGN_IN_CANCELED','CANCELED','CANCELLED'].includes(code))return;console.error('AquiPay Google Sign-In failed',{code,message});const r=$('err');if(r)r.textContent=message||'Não foi possível iniciar sessão com Google. Verifica a configuração OAuth Android e tenta novamente.'}return}const box=$('gbtn');if(box&&!box.querySelector('iframe')){box.innerHTML='<button class="btn secondary" type="button">'+GLOGO+'Continuar com Google</button>';await initGoogle()}if(!window.google?.accounts?.id){const r=$('err');if(r)r.textContent='Não foi possível carregar o início de sessão com Google. Verifica a ligação e tenta novamente.'}},togglePassword(el){const input=$(el.dataset.id);if(!input)return;const show=input.type==='password';input.type=show?'text':'password';el.innerHTML=ic(show?'eyeOff':'eye');el.setAttribute('aria-label',show?'Ocultar palavra-passe':'Mostrar palavra-passe')},openDoc(el){closeSheet();S.doc=el.dataset.id;if(DOCS[S.doc])history.replaceState(null,'',docUrl(S.doc));go('doc')},
