async login(){
 const l=$('le').value.trim().toLowerCase(),p=$('lp').value,r=$('err');
 if(!l||!p)return r.textContent='Preenche todos os campos.';
 try{
  const res=await fetch(CFG.apiBase+'/api/auth/login',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({email:l,password:p})});
  const cloud=await res.json().catch(()=>({}));
  if(!res.ok)throw new Error(cloud.error||'Não foi possível autenticar.');
  if(cloud.requiresTwoFactor&&cloud.challengeId){S.authChallenge=cloud.challengeId;S.authGoogle=false;render();return}
  if(!cloud.token||!cloud.user)throw new Error('Resposta de autenticação inválida.');
  let u=S.users.find(x=>x.cloudId===cloud.user.id)||S.users.find(x=>x.email===l);
  if(!u)u={id:nid(),nome:cloud.user.name,email:cloud.user.email,coins:0,at:Date.now(),daily:{date:day(),count:0}};
  u.apiToken=cloud.token;u.cloudId=cloud.user.id;u.nome=cloud.user.name;u.email=cloud.user.email;
  delete u.pw;
  u.deletionRequestedAt=cloud.user.deletionRequestedAt||null;u.deletionDueAt=cloud.user.deletionDueAt||null;
  await saveUser(u);if(!S.users.some(x=>x.id===u.id))S.users.push(u);
  return enter(u);
 }catch(e){r.textContent=e.message||'Não foi possível ligar ao servidor. Tenta novamente.'}
},
async register(){const n=$('rn').value.trim(),e=$('re').value.trim().toLowerCase(),p=$('rp').value,r=$('err');if(!n||!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e))return r.textContent='Indica o nome e um email válido.';if(p.length<10)return r.textContent='A palavra-passe deve ter pelo menos 10 caracteres.';if(S.users.some(x=>x.email===e))return r.textContent='Este email já está registado.';let cloud;try{const res=await fetch(CFG.apiBase+'/api/auth/register',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({name:n,email:e,password:p})});cloud=await res.json();if(!res.ok)throw new Error(cloud.error||'Não foi possível criar a conta online.')}catch(e){return r.textContent=e.message||'Não foi possível ligar ao servidor.'}const id=nid(),u={id,nome:n,email:e,apiToken:cloud.token,cloudId:cloud.user.id,publicProfile:true,coins:10,plusUntil:null,daily:{date:day(),count:0},at:Date.now()};S.users.push(u);await saveUser(u);await enter(u);notify(u.id,'Bem-vindo ao Aquipay. Recebeste 10 créditos de boas-vindas.','novidades')},
