async send(el){const v=S.vagas.find(x=>x.id===el.dataset.id),u=S.me;if(!v)return;const proposalMessage=$('proposalMessage')?.value.trim()||'';if(proposalMessage.length<10)return toast('Escreve uma proposta com pelo menos 10 caracteres.');const rawPrice=$('proposalPrice')?.value.trim()||'';let proposalPriceMinor=null;if(rawPrice){const amount=Number(rawPrice);if(!Number.isFinite(amount)||amount<0||!Number.isSafeInteger(Math.round(amount*100)))return toast('Indica um valor válido na moeda selecionada.');proposalPriceMinor=Math.round(amount*100)}const used=S.usage?.applicationsToday??localApplicationsToday();if(!hasPlus(u)&&used>=5){closeSheet();toast('Atingiste as 5 candidaturas gratuitas de hoje.');return}let remote=null;if(u.apiToken&&v.cloudListingId){try{remote=await api('/api/proposals',{method:'POST',body:JSON.stringify({listingId:v.cloudListingId,message:proposalMessage,priceMinor:proposalPriceMinor})});S.usage={...(S.usage||{}),applicationsToday:remote.applicationsToday??used+1,plusActive:remote.plusActive??hasPlus(u)}}catch(e){closeSheet();toast(e.message);return}}else if(!hasPlus(u)&&used>=5){closeSheet();toast('Atingiste as 5 candidaturas gratuitas de hoje.');return}const k={id:nid(),vagaId:v.id,userId:u.id,ownerId:v.ownerId,spent:0,priceMinor:proposalPriceMinor,status:'enviada',at:Date.now()};if(remote?.proposalId)k.cloudProposalId=remote.proposalId;S.cands.push(k);S.usage={...(S.usage||{}),applicationsToday:remote?.applicationsToday??used+1,plusActive:remote?.plusActive??hasPlus(u)};await put('cands',k);closeSheet();render();if(remote?.conversationId){toast('Proposta enviada com sucesso.');await A.openConversation({dataset:{id:remote.conversationId,name:U(v.ownerId)?.nome||'Responsável'}})}else{go('home');toast('Candidatura enviada')}notify(v.ownerId,`${u.nome} candidatou-se a «${v.titulo}».`)},
cands(el){const v=S.vagas.find(x=>x.id===el.dataset.id),l=S.cands.filter(c=>c.vagaId===v.id);sheet(`<h3 style="margin-bottom:.8rem">${esc(v.titulo)}</h3>${l.length?l.map(c=>{const u=U(c.userId)||{nome:'Utilizador'},nx=c.status==='enviada'?['Aceitar','aceite']:c.status==='aceite'&&v.tipo==='biscato'?['Confirmar conclusão','concluida']:null;return`<div class="card"><div class="ho">${av(u,40)}<div><b>${esc(u.nome)}</b><small>${esc(u.cidade||'')} · ${T(ST[c.status])}</small>${c.priceMinor!=null?`<small>Valor proposto: ${kz(c.priceMinor/100)}</small>`:''}</div></div>${u.bio?`<p class="ds" style="margin-top:.5rem">${esc(u.bio)}</p>`:''}${nx?`<button class="btn" style="margin-top:.7rem" data-a="step" data-id="${c.id}" data-v="${nx[1]}">${nx[0]}</button>`:''}</div>`}).join(''):'<p class="mut">Ainda ninguém se candidatou.</p>'}`)},
