async loadBillingCatalog(){if(!isNativeApp())return;try{const billing=await import('./js/purchases.js');const ready=await billing.initPurchases();if(!ready.ok)return;const products=await billing.loadCoinProducts();S.storeProducts=Object.fromEntries((products||[]).map(p=>[p.identifier||p.productIdentifier,p]));const plus=await billing.loadPlusProduct().catch(()=>[]);if(plus?.[0])S.storeProducts.plus=plus[0];render()}catch(e){console.warn('Google Play catalog',e)}},
  async checkout(el){if(!S.me?.apiToken)return toast('Inicia sessão para comprar.');if(!isNativeApp())return toast('As compras estão disponíveis na aplicação Android instalada pela Google Play.');try{el.disabled=true;const billing=await import('./js/purchases.js');const ready=await billing.initPurchases();if(!ready.ok)throw new Error('A Google Play Billing não está disponível neste dispositivo.');if(el.dataset.id==='plus'){const result=await billing.buyPlus(api);if(!result.plusActive)throw new Error('A Google Play não confirmou a ativação do Plus.');S.usage={...(S.usage||{}),plusActive:true};}else{const productId='coins_'+String(Number(el.dataset.id));const result=await billing.buyCoins(productId,api);const account=await api('/api/me');S.me.coins=Number(account.wallet?.available_coins??result.balance??0);S.usage={...(S.usage||{})};}await refreshData();render();toast(el.dataset.id==='plus'?'Plano Plus ativado com sucesso.':'Créditos creditadas com sucesso.')}catch(e){toast(e.message||'Não foi possível concluir a compra.')}finally{el.disabled=false}},
