async exportData(){const u={...S.me};['pw','apiToken','foto'].forEach(k=>delete u[k]);const data={exportadoEm:new Date().toISOString(),conta:u,anuncios:S.vagas.filter(v=>v.ownerId===S.me.id).map(({fotos,...r})=>r),candidaturas:S.cands.filter(c=>c.userId===S.me.id||c.ownerId===S.me.id),notificacoes:S.notifs.filter(n=>n.uid===S.me.id),avaliacoes:S.reviews.filter(r=>r.ownerId===S.me.id||r.targetId===S.me.id||r.reviewerId===S.me.id)};const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.download='aquipay-os-meus-dados.json';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Ficheiro gerado')},
