askDelete(){const u=S.me,g=!!u.google,m=CFG.supportEmail,q=encodeURIComponent(T('Peço a eliminação da minha conta Aquipay ({a}).',{a:u.email||''}));sheet(`<h3 style="margin-bottom:.5rem">Pedir eliminação da conta</h3><p class="mut" style="margin-bottom:1rem">A tua conta será desativada e deixará de aparecer no Aquipay imediatamente. Os dados serão eliminados permanentemente após 30 dias. Durante esse prazo, podes voltar a iniciar sessão e cancelar o pedido.</p><p class="err" id="perr" role="alert"></p>${g?fd('Email da conta','dce','email','','autocomplete="off"'):fd('Palavra-passe atual','dcp','password','','autocomplete="current-password"')}<p class="mut" style="margin:.4rem 0 1rem">${g?'Para confirmar, escreve o email da tua conta.':'Para confirmar, escreve a palavra-passe da tua conta.'}</p>${fd('Código do autenticador (se ativado)','dctotp','text','Código de 6 dígitos ou recuperação')}<div class="stack"><button class="btn" style="background:var(--bad)" data-a="deleteAccount">Confirmar pedido de eliminação</button><button class="btn secondary" data-a="close">Cancelar</button><a class="link" style="text-align:center" href="https://aquipay.isabstudio.dev/delete-account.html">Pedir eliminação pela página web</a></div>`)},
async deleteAccount(){const u=S.me,g=!!u.google,v=(g?$('dce'):$('dcp')).value,e=$('perr');if(!v)return e.textContent=T('Preenche todos os campos.');if(!u.apiToken)return e.textContent='Inicia sessão com internet para registar o pedido de eliminação.';try{await api('/api/me',{method:'DELETE',body:JSON.stringify({... (g?{confirmEmail:v}:{password:v}),code:$('dctotp')?.value.trim()||''})})}catch(x){return e.textContent=x.message}const id=u.id,mine=S.vagas.filter(x=>x.ownerId===id).map(x=>x.id),gone={users:[id],vagas:mine,cands:S.cands.filter(c=>c.userId===id||c.ownerId===id||mine.includes(c.vagaId)).map(c=>c.id),notifs:S.notifs.filter(n=>n.uid===id).map(n=>n.id),reviews:S.reviews.filter(r=>r.ownerId===id||r.reviewerId===id||r.targetId===id).map(r=>r.id),messages:S.messages.filter(x=>x.from===id||x.to===id).map(x=>x.id)};for(const[st,ids]of Object.entries(gone))for(const x of ids)try{await del(st,x)}catch{}for(const st of Object.keys(gone))S[st]=S[st].filter(r=>!gone[st].includes(r.id));const bl={...(S.st.blocks||{})};delete bl[id];S.st.blocks=bl;await put('kv',S.st);S.me=null;S.v='home';await put('kv',{id:'session',uid:null});closeSheet();render();toast('Pedido registado. A eliminação permanente será em 30 dias.')},
