askPassword(){if(S.me.google)return toast('Esta conta usa o Google para entrar.');sheet(`<h3 style="margin-bottom:.8rem">Alterar palavra-passe</h3><p class="err" id="perr" role="alert"></p>${fd('Palavra-passe atual','pwc','password','','autocomplete="current-password"')}${fd('Nova palavra-passe','pwn','password','Mínimo 10 caracteres','autocomplete="new-password"')}${fd('Código do autenticador (se ativado)','pw2fa','text','Código de 6 dígitos','inputmode="text"')}<div class="stack" style="margin-top:.8rem"><button class="btn" data-a="changePassword">Guardar palavra-passe</button><button class="btn secondary" data-a="close">Cancelar</button></div>`)},
