let searchTimer,globalSearchRenderTimer;document.addEventListener('input',e=>{if(S.v==='pub'&&['pt','pp','pl','pd'].includes(e.target.id))persistListingDraft();if(e.target.id==='publicSearch'){const q=e.target.value.trim(),box=$('publicResults');if(!box)return;clearTimeout(searchTimer);if(q.length<2){box.innerHTML='<p class="mut">Escreve pelo menos 2 caracteres.</p>';return}searchTimer=setTimeout(async()=>{try{const d=await fetch(CFG.apiBase+'/api/users?q='+encodeURIComponent(q),{headers:authH()}).then(r=>r.json());box.innerHTML=(d.users||[]).filter(u=>!remoteBlocked(u.id)).map(u=>`<div class="card ho"><div class="av">${esc((u.name||'?').slice(0,2).toUpperCase())}</div><div style="flex:1"><b>${esc(u.name)}</b><small>${esc(u.city||'')}</small></div><button class="btn secondary" style="width:auto" data-a="viewProfile" data-id="${u.id}">Ver perfil</button></div>`).join('')||'<p class="mut">Nenhum perfil público encontrado.</p>'}catch{box.innerHTML='<p class="mut">Não foi possível pesquisar agora.</p>'}},250)}if(e.target.id==='networkSearch'){clearTimeout(searchTimer);const q=e.target.value.trim();searchTimer=setTimeout(()=>{api('/api/network?q='+encodeURIComponent(q)).then(d=>{S.networkUsers=d.users||[];const box=$('networkResults');if(box)box.innerHTML=S.networkUsers.length?S.networkUsers.map(networkCard).join(''):empty('Não encontrámos perfis','Experimenta pesquisar por outra profissão ou nome.')}).catch(()=>{})},250)}if(e.target.id==='globalSearch'){S.searchText=e.target.value;clearTimeout(globalSearchRenderTimer);globalSearchRenderTimer=setTimeout(()=>{const f=$('feed');if(f)f.innerHTML=feed()},120);clearTimeout(searchTimer);const q=S.searchText.trim();if(q.length>=2){searchTimer=setTimeout(async()=>{try{const d=await fetch(CFG.apiBase+'/api/users?q='+encodeURIComponent(q),{headers:authH()}).then(r=>r.json());S.remotePeople=(d.users||[]).filter(u=>!remoteBlocked(u.id));const box=$('feed');if(box&&S.remotePeople.length){box.insertAdjacentHTML('beforeend',`<h4>Perfis encontrados</h4>${S.remotePeople.map(u=>`<div class="card ho"><div class="av">${esc((u.name||'?').slice(0,2).toUpperCase())}</div><div style="flex:1"><b>${esc(u.name)}</b><small>${esc(u.city||'')}</small></div><button class="btn secondary" style="width:auto" data-a="viewProfile" data-id="${u.id}">Ver perfil</button></div>`).join('')}`)}}catch{}},250)}else S.remotePeople=[]}});
document.addEventListener('change',e=>{if(S.v==='pub'&&['ptipo','pcountry'].includes(e.target.id))persistListingDraft();const g=e.target.dataset.set;if(g){const on=e.target.checked;if(g==='publicProfile'){S.me.publicProfile=on;saveUser(S.me).then(syncProfile)}else if(g.startsWith('notif.')){const key=g.slice(6);S.st.notif={...S.st.notif,[key]:on,...(key==='novidades'?{novidadesExplicit:true}:{})};put('kv',S.st);syncPush()}else if(g.startsWith('feedback.')){const key=g.slice(9);S.st.feedback={...(S.st.feedback||{}),[key]:on};put('kv',S.st);if(on)buttonFeedback('tap')}return}const k=e.target.dataset.k;if(!k)return;if(k==='lang'){A.lang({dataset:{id:e.target.value}});return}S.st[k]=k==='size'?+e.target.value:e.target.value;put('kv',S.st);if(k==='feedCountry'){S.st.feedCountryChosen=true;refreshData().catch(()=>{});render();return}theme()});
let modalTouchY=0,modalTouchX=0,modalDrag=false;
const modal=$('sh');
modal.addEventListener('touchstart',e=>{if(!modal.classList.contains('on')||e.touches.length!==1)return;const t=e.target;if(t.closest('input,textarea,select,button,a,[contenteditable="true"]'))return;modalTouchY=e.touches[0].clientY;modalTouchX=e.touches[0].clientX;modalDrag=false},{passive:true});
modal.addEventListener('touchmove',e=>{if(!modalTouchY||!modal.classList.contains('on')||e.touches.length!==1)return;const dy=e.touches[0].clientY-modalTouchY,dx=e.touches[0].clientX-modalTouchX;if(Math.abs(dx)>Math.abs(dy)||dy<=0||modal.scrollTop>0)return;if(dy>8){e.preventDefault();modalDrag=true;modal.style.transition='none';modal.style.transform=`translateY(${dy}px)`}},{passive:false});
modal.addEventListener('touchend',e=>{if(!modalTouchY)return;const dy=e.changedTouches[0].clientY-modalTouchY;modalTouchY=0;modalTouchX=0;if(modalDrag&&dy>105){modalDrag=false;closeSheet()}else if(modalDrag){modalDrag=false;modal.style.transition='transform .32s cubic-bezier(.32,.72,0,1)';modal.style.transform='translateY(0)';setTimeout(()=>{if(modal.classList.contains('on'))modal.style.transition=''},340)}},{passive:true});
modal.addEventListener('touchcancel',()=>{modalTouchY=0;modalTouchX=0;if(modalDrag){modalDrag=false;modal.style.transition='transform .32s cubic-bezier(.32,.72,0,1)';modal.style.transform='translateY(0)';setTimeout(()=>{if(modal.classList.contains('on'))modal.style.transition=''},340)}},{passive:true});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('sh').classList.contains('on'))closeSheet();if(e.key==='Enter'&&e.target.matches('.auth input')){const b=document.querySelector('.auth [data-a=login],.auth [data-a=register],.auth [data-a=doReset]');if(b)b.click()}});
window.addEventListener('aquipay:backbutton',()=>{if($('sh')?.classList.contains('on')){closeSheet();return}if(document.activeElement?.matches('input,textarea,select,[contenteditable="true"]')){document.activeElement.blur();return}A.back()});
let pullStartY=0,pullScroller=null,pullBusy=false;document.addEventListener('touchstart',e=>{pullScroller=null;if(!S.me||!['home','messages','nt','cand','mine'].includes(S.v)||e.target.closest('input,textarea,select,button,a,[contenteditable="true"]'))return;const sc=e.target.closest('.main');if(sc&&sc.scrollTop<=0&&!$('sh')?.classList.contains('on')){pullScroller=sc;pullStartY=e.touches[0].clientY}},{passive:true});document.addEventListener('touchend',async e=>{if(!pullStartY||pullBusy)return;const sc=pullScroller,delta=e.changedTouches[0].clientY-pullStartY;pullStartY=0;pullScroller=null;if(!sc||sc.scrollTop>0||delta<85||!S.me||!['home','messages','nt','cand','mine'].includes(S.v))return;pullBusy=true;toast('A atualizar…');try{await refreshData();if(S.v==='messages'){const d=await api('/api/conversations');S.conversations=d.conversations||[]}toast('Informação atualizada.')}catch{toast('Não foi possível atualizar o conteúdo. Tenta novamente dentro de instantes.')}finally{pullBusy=false}},{passive:true});
addEventListener('online',()=>toast('Ligação restabelecida'));addEventListener('offline',()=>toast('Sem ligação. Podes continuar a usar o Aquipay.'));

